  --color-neutral-0:    #FFFFFF;
  --color-neutral-50:   #F5F5F7;
  --color-neutral-100:  #EBEBF0;
  --color-neutral-200:  #C7C7CC;
  --color-neutral-300:  #A8A8AD;
  --color-neutral-500:  #8E8E93;
  --color-neutral-700:  #3A3A3C;     /* elevated card */
  --color-neutral-800:  #1C1C1E;     /* surface */
  --color-neutral-900:  #0A0A0A;
  --color-neutral-1000: #000000;     /* canvas */

  /* Semantic (dark-coherent: 깊은 배경 + 밝은 전경) */
  --color-success-bg: #11301C;
  --color-success-fg: #30D158;
  --color-warning-bg: #3A2A0A;
  --color-warning-fg: #FFB340;
  --color-error-bg:   #3A1418;
  --color-error-fg:   #FF453A;
  --color-info-bg:    #0A2540;
  --color-info-fg:    #0A84FF;

  /* Surface */
  --bg-base:     #000000;
  --bg-subtle:   #1C1C1E;
  --bg-elevated: #2C2C2E;
  --bg-overlay:  rgba(0,0,0,0.70);

  /* Text */
  --text-primary:    #FFFFFF;
  --text-secondary:  #EBEBF5;
  --text-tertiary:   #A8A8AD;
  --text-on-primary: #FFFFFF;
  --text-disabled:   #636366;

  /* Border */
  --border-default: #2C2C2E;
  --border-subtle:  #1C1C1E;
  --border-strong:  #3A3A3C;
  --border-focus:   #FF3B58;
}

